#include "cover_arithmetic.hpp"
std::string gkey(const G&a){return a.u.key()+"|"+a.v.key();}
G reduce4(P u,P v){require(((v*v-curve)%u).degree()<0,"Prym pullback equation");while(u.degree()>3){P n=(curve-v*v).exact(u).monic();v=(-v)%n;u=n;}G a{u.monic(),v};a.check();return a;}
G pull_prym(const Json&point,F lc){P u=polynomial(point.arr.at(0)),v=polynomial(point.arr.at(1));require(u.degree()==2&&v.degree()<=1,"Prym pullback fixture shape");F u0=u.at(0)/(lc*lc),u1=u.at(1)/lc,v0=v.at(0)/(lc*lc),v1=v.at(1)/lc;
    P X{F(0),F(1)},A{F(1),cc},cx=X.scale(cc),A2=A*A,cx2=cx*cx;P U=(cx2*cx2).scale(u0)+(cx2*A2).scale(u1)+A2*A2;require(U.degree()==4,"Prym pullback degree4");U=U.monic();auto[g,s,t]=xgcd(A,U);require(g.degree()==0,"Prym pullback pole");P V=((X*X*X)*(A2.scale(v1)+cx2.scale(v0))).scale(F(1)/cc)*s;return reduce4(U,V%U);
}
G gfrob(const G&a){auto u=a.u.c,v=a.v.c;for(auto&x:u)x=x.power(prime);for(auto&x:v)x=x.power(prime);return {P(u),P(v)};}
G combination(const std::vector<G>&basis,const std::vector<int>&a){require(basis.size()==a.size(),"coordinate length");G out;for(size_t i=0;i<a.size();++i){require(a[i]>=0&&a[i]<3,"coordinate F3");if(a[i])out=out.add(a[i]==1?basis[i]:basis[i].neg());}return out;}
void emit_f(const F&a){std::cout<<'[';for(int i=0;i<modulus.degree();++i)std::cout<<(i?",":"")<<'"'<<a.a.at(i).x<<'"';std::cout<<']';}
void emit_p(const P&p){std::cout<<'[';for(int i=0;i<=p.degree();++i){if(i)std::cout<<',';emit_f(p.at(i));}std::cout<<']';}
int main(int argc,char**argv){try{require(argc==5,"usage: kernel_point_replay prym.json pairings.json elliptic.json kernels.jsonl");auto j=read_json(argv[1]),pair=read_json(argv[2]),ell=read_json(argv[3]);prime=mpz_class(j.at("source_model").at("p").scalar);modulus=base_poly(j.at("finite_field_modulus_coefficients"));require(modulus==base_poly(ell.at("finite_field_modulus_coefficients")),"common torsion field");F b(Poly<Z>{Z(mpz_class(j.at("source_model").at("b").scalar))});dd=F(7);P t{F(0),F(1)},one{F(1)},t2=t*t,tm=t2-one,td=t2+P{dd};P h=tm*(td*td*td-(td*tm*tm).scale(F(3))+(tm*tm*tm).scale(b));cc=F(1024);std::vector<F> q(8);for(int i=0;i<=8;++i){long choose=1;F cp(1);for(int k=1;k<=i;++k){choose=choose*(i-k+1)/k;cp=cp*cc;q[8-k]=q[8-k]+h.at(i)*F(choose)/cp;}}curve=P(q);require(curve.degree()==7&&curve.c.back()==F(1),"odd cover model");
    F ez=field(ell.at("primitive_third_root_coefficients")),pz=field(pair.at("Prym_pairing").at("primitive_third_root_coefficients"));bool align=ez!=pz;require(!align||ez*ez==pz,"third-root alignment");
    std::vector<G> basis;for(auto&v:ell.at("basis_point_coefficients").arr){EC a(field(v.arr.at(0)),field(v.arr.at(1)));if(align)a=EC(a.x.power(prime),a.y.power(prime));basis.push_back(pull(a));}F lc=b-F(2);for(auto&p:j.at("basis_Mumford_coefficients").arr)basis.push_back(pull_prym(p,lc));require(basis.size()==6,"six cover torsion generators");
    for(auto&a:basis){a.check();require(!(a==G{})&&a.times(3)==G{},"actual cover order3");}
    for(int i=0;i<6;++i){std::vector<int>a(6);if(i<2){for(int k=0;k<2;++k)a[k]=ell.at("Frobenius_matrix_mod3").arr[i].arr[k].integer();}else{for(int k=0;k<4;++k)a[k+2]=j.at("Prym_Frobenius_matrix_mod3").arr[i-2].arr[k].integer();}require(combination(basis,a)==gfrob(basis[i]),"actual cover Frobenius action");}
    // Independence is checked in actual divisor arithmetic, not inferred from labels.
    std::vector<G> all{G{}};for(auto&a:basis){auto old=all;for(auto&w:old){all.push_back(w.add(a));all.push_back(w.add(a.neg()));}}
    std::set<std::string> distinct;for(auto&a:all)distinct.insert(gkey(a));require(distinct.size()==729,"actual six-dimensional cover basis");
    // Rational Prym 3-torsion has zero elliptic norm. Test its actual nonzero classes.
    int rational_prym=0;for(int code=1;code<81;++code){int n=code;std::vector<int>a(6);for(int k=2;k<6;++k){a[k]=n%3;n/=3;}bool fixed=true;std::vector<int> f(6);for(int k=2;k<6;++k)for(int v=2;v<6;++v)f[v]=(f[v]+a[k]*j.at("Prym_Frobenius_matrix_mod3").arr[k-2].arr[v-2].integer())%3;fixed=f==a;if(!fixed)continue;G point=combination(basis,a);require(gfrob(point)==point&&norm(point).zero,"rational Prym torsion projects to zero");++rational_prym;}require(rational_prym==2,"rational Prym nonzero count");
    std::ifstream in(argv[4]);require(bool(in),"kernel input");std::string line;int kernels=0;while(std::getline(in,line)){Parser p{line};Json k=p.value();std::vector<G> generators;std::vector<std::vector<int>> coordinates;for(auto&row:k.at("rref_basis").arr){std::vector<int>a;for(auto&v:row.arr)a.push_back(v.integer());generators.push_back(combination(basis,a));coordinates.push_back(a);}require(generators.size()==3,"kernel generator count");
        // Each pullback scales its canonical polarization by2. After root alignment,
        // the actual transported form is a common nonzero scalar times this form.
        for(auto&a:coordinates)for(auto&b0:coordinates){int value=0;for(int i=0;i<6;++i)for(int v=0;v<6;++v){int entry=0;if(i<2&&v<2)entry=ell.at("canonical_Weil_matrix_mod3").arr[i].arr[v].integer();if(i>=2&&v>=2)entry=pair.at("Prym_pairing").at("canonical_Prym_Weil_matrix_mod3").arr[i-2].arr[v-2].integer();value+=a[i]*entry*b0[v];}require(value%3==0,"transported kernel isotropy");}
        std::vector<G> points{G{}};for(auto&a:generators){auto old=points;for(auto&w:old){points.push_back(w.add(a));points.push_back(w.add(a.neg()));}}std::set<std::string> set;for(auto&a:points){a.check();require(a.times(3)==G{},"actual kernel order");set.insert(gkey(a));}require(set.size()==27,"actual kernel size");for(auto&a:generators)require(set.count(gkey(gfrob(a))),"actual kernel Frobenius stability");++kernels;}
    require(kernels==8,"eight actual kernels");std::cout<<"{\"scope\":\"P192 d7 actual J(H)[3] basis on monic degree7 model\",\"standing\":\"producer-unverified\",\"elliptic_basis_frobenius_alignment\":"<<(align?"true":"false")<<",\"basis\":[";for(size_t i=0;i<basis.size();++i){if(i)std::cout<<',';std::cout<<"{\"U\":";emit_p(basis[i].u);std::cout<<",\"V\":";emit_p(basis[i].v);std::cout<<'}';}std::cout<<"]}\n";
    std::cerr<<"PASS actual genus3 torsion: 6 order3 basis classes;729 distinct classes; actual Frobenius action;8 kernels of27 elements each, stable under Frobenius;2 nonzero rational Prym classes have zero elliptic norm; common-root basis alignment="<<align<<"\n";
}catch(const std::exception&e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
